'use strict';
window.AdvancedFilters=(()=>{
 const $=id=>document.getElementById(id),clone=PresetTools.clone;
 let catalog=null,current=clone(PresetTools.DEFAULT),callback=()=>{},getListings=()=>[],ready=false;
 const library=new Map([[current.name,clone(current)]]);
 const unit=o=>Object.fromEntries(Object.entries(o).filter(([,v])=>v!==null&&v!==undefined).map(([k,v])=>['Offer / '+k,[v]]));
 const node=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
 function message(text,error=false){$('preset-message').textContent=text;$('preset-message').classList.toggle('validation-error',error);}
 function coverage(){const q=current.query,locationSupported=q.location.trim()==='33844';return {source:'local-snapshot',live:false,locationSupported,partial:!locationSupported||q.radiusMiles>20||q.maxRent===null||q.maxRent>2300||q.minBeds<2||q.maxBeds===null||q.maxBeds>3,available:{location:'33844',radiusMiles:20,minBeds:2,maxBeds:3,maxRent:2300},message:!locationSupported?'No live-source connection for this location. No results are evaluated against the wrong center.':q.radiusMiles>20||q.maxRent===null||q.maxRent>2300||q.minBeds<2||q.maxBeds===null||q.maxBeds>3?'Partial coverage: this saved catalog only contains 2–3 bed rentals up to $2,300 within 20 miles of 33844.':'Saved catalog · not a live availability search.'};}
 function emit(){callback();$('coverage-note').textContent=coverage().message;$('scope-label').textContent=`${current.query.location} · ${current.query.radiusMiles} mi`;$('current-preset').textContent=current.name;document.dispatchEvent(new CustomEvent('nearby:preset-changed',{detail:{preset:clone(current),coverage:coverage()}}));}
 function sync(){
  for(const k of ['location','radiusMiles','minRent','maxRent','minBeds','maxBeds','text','sort'])$('q-'+k).value=current.query[k]??'';
  $('q-propertyTypes').value=current.query.propertyTypes.join(', ');
  $('preset-name').value=current.name;
  $('json-editor').value=JSON.stringify(current,null,2);renderRules();renderLibrary();
 }
 function renderLibrary(){const sel=$('preset-picker');sel.replaceChildren();for(const name of library.keys()){const o=node('option',name);o.value=name;sel.append(o);}sel.value=library.has(current.name)?current.name:'';}
 function apply(p){const validation=PresetTools.validate(p,catalog?.fields);if(!validation.valid)throw Error(validation.errors.join('\n'));current=clone(p);sync();emit();message('Preset applied. '+coverage().message);return {preset:clone(current),coverage:coverage(),results:results()};}
 function resultFor(l){const offers=l.offers.filter(o=>offerMatches(o));return FilterEngine.evaluate(catalog?.records[l.property_id],current.rules,offers.map(unit));}
 function matches(l){const q=current.query;return coverage().locationSupported&&l.radius_miles<=q.radiusMiles&&(!q.propertyTypes.length||q.propertyTypes.includes(l.property_type))&&(!q.text||`${l.name} ${l.address||''} ${l.city} ${l.zip}`.toLowerCase().includes(q.text.toLowerCase()))&&l.offers.some(offerMatches)&&resultFor(l).match;}
 function offerMatches(o){const q=current.query;return o.beds>=q.minBeds&&(q.maxBeds===null||o.beds<=q.maxBeds)&&o.rent>=q.minRent&&(q.maxRent===null||o.rent<=q.maxRent)&&current.rules.filter(r=>r.mode!=='prefer'&&r.field.startsWith('Offer / ')).every(r=>FilterEngine.passes(unit(o)[r.field],r));}
 function results(){const list=getListings().filter(matches);list.sort((a,b)=>resultFor(b).score-resultFor(a).score||sortValue(a,b));return list.map(l=>({propertyId:l.property_id,name:l.name,score:resultFor(l).score,offers:l.offers.filter(offerMatches)}));}
 function sortValue(a,b){const pick=l=>l.offers.filter(offerMatches).sort((x,y)=>current.query.sort==='space'?(y.sqft||0)-(x.sqft||0)||x.rent-y.rent:x.rent-y.rent)[0];if(current.query.sort==='price')return pick(a).rent-pick(b).rent;if(current.query.sort==='space')return (pick(b).sqft||0)-(pick(a).sqft||0);if(current.query.sort==='photos')return b.photo_count-a.photo_count;return a.radius_miles-b.radius_miles;}
 function explain(id){const l=getListings().find(l=>l.property_id===String(id));if(!l)throw Error('Unknown property ID');const record=catalog.records[l.property_id];return {propertyId:l.property_id,match:matches(l),score:resultFor(l).score,coverage:coverage(),rules:current.rules.map(r=>{const values=r.field.startsWith('Offer / ')?record.offers.flatMap(o=>o[r.field]||[]):record.fields[r.field]||[];return {rule:clone(r),known:values.length>0,matched:FilterEngine.test(values,r),...(r.op==='mentions'?PresetTools.mentions(values,r):{}),note:r.field.startsWith('Offer / ')?'Evidence spans offers; final result requires one eligible offer to satisfy all offer rules.':r.field==='description'?'Text evidence only; not a verified amenity.':undefined};})};}
 function renderRules(){const target=$('rule-list');target.replaceChildren();$('advanced-count').textContent=String(current.rules.length);if(!current.rules.length)target.append(node('p','No extra rules. Add a field condition or description mention rule.'));current.rules.forEach((r,i)=>{const row=node('article');row.className='rule-summary';const head=node('strong',`${r.mode.toUpperCase()} · ${r.field}`);const text=node('p',r.op==='mentions'?`${r.match==='all'?'All':'Any'}: ${r.terms.join(' / ')}${(r.excludeTerms||[]).length?' · except '+r.excludeTerms.join(' / '):''}`:`${r.op} ${r.value??''}`);const meta=node('small',`${r.allowUnknown?'Allow missing':'Omit missing'}${r.mode==='prefer'?' · weight '+(r.weight??1):''}${r.op==='mentions'?' · '+(r.wholeWord?'whole phrase':'substring')+(r.ignoreNegated?' · negation heuristic':''):''}`);const edit=node('button','Edit JSON');edit.type='button';edit.onclick=()=>{$('json-workspace').open=true;$('json-editor').focus();};const remove=node('button','Remove');remove.type='button';remove.setAttribute('aria-label',`Remove rule ${i+1}: ${r.field}`);remove.onclick=()=>{const p=clone(current);p.rules.splice(i,1);apply(p);};row.append(head,text,meta,edit,remove);target.append(row);});}
 function fields(){const query=$('field-search').value.toLowerCase();const sel=$('field-picker');sel.replaceChildren();catalog.fields.filter(f=>f.key.toLowerCase().includes(query)||f.values.some(v=>String(v).toLowerCase().includes(query))).forEach(f=>{const o=node('option',`${f.key} · ${f.type}`);o.value=f.key;sel.append(o);});$('add-rule').disabled=!sel.options.length;fieldChanged();}
 function fieldChanged(){const def=catalog.fields.find(f=>f.key===$('field-picker').value);const op=$('field-op');op.replaceChildren();let choices=def?.type==='number'?['gte','lte','equals']:def?.type==='date'?['after','before','equals']:['contains','equals'];for(const value of [...choices,'known','unknown']){const o=node('option',({gte:'At least',lte:'At most',after:'On/after',before:'On/before',known:'Has a value',unknown:'Value missing',contains:'Contains',equals:'Equals'})[value]);o.value=value;op.append(o);}const dl=$('field-values');dl.replaceChildren();for(const v of def?.values||[]){const o=node('option');o.value=String(v);dl.append(o);}$('field-value').disabled=false;}
 function download(name,data){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=node('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 function importData(data){let list;if(data.version===1)list=PresetTools.migrate(data);else if(data.version===2&&Array.isArray(data.presets))list=data.presets;else list=[data];if(list.length>100)throw Error('Maximum 100 presets per import');const validations=list.map(p=>PresetTools.validate(p,catalog.fields));const errors=validations.flatMap((v,i)=>v.errors.map(e=>`Preset ${i+1}: ${e}`));if(errors.length)throw Error(errors.join('\n'));for(const p of list)library.set(p.name,clone(p));renderLibrary();message(`Imported ${list.length} presets. Select one and press Apply preset.`);return {imported:list.length};}
 function safe(fn){return (...args)=>{try{return fn(...args);}catch(e){message(e.message,true);}};}
 return {
  async init(onChange,listings){callback=onChange;getListings=listings;const r=await fetch('data/filters.json');if(!r.ok)throw Error('Field catalog unavailable');catalog=await r.json();ready=true;
   $('field-count').textContent=catalog.fields.length;fields();sync();
   $('query-form').onsubmit=e=>{e.preventDefault();safe(()=>{const p=clone(current);for(const k of ['location','text','sort'])p.query[k]=$('q-'+k).value.trim();for(const k of ['radiusMiles','minRent','maxRent','minBeds','maxBeds'])p.query[k]=$('q-'+k).value===''&&['maxRent','maxBeds'].includes(k)?null:Number($('q-'+k).value);p.query.propertyTypes=$('q-propertyTypes').value.split(',').map(x=>x.trim()).filter(Boolean);apply(p);})();};
   $('apply-preset').onclick=safe(()=>apply(library.get($('preset-picker').value)));
   $('reset').onclick=()=>apply(PresetTools.DEFAULT);
   $('save-preset').onclick=safe(()=>{const p=clone(current);p.name=$('preset-name').value.trim();const v=PresetTools.validate(p,catalog.fields);if(!v.valid)throw Error(v.errors.join('\n'));library.set(p.name,clone(p));apply(p);message('Saved for this session. Export to keep it.');});
   $('export-preset').onclick=()=>download('nearby-preset.json',current);$('export-presets').onclick=()=>download('nearby-presets.json',{version:2,presets:[...library.values()]});
   $('import-presets').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error('Maximum JSON file size: 1 MB');importData(JSON.parse(await f.text()));}catch(err){message(err.message,true);}finally{e.target.value='';}};
   $('validate-json').onclick=safe(()=>{const p=JSON.parse($('json-editor').value);const v=PresetTools.validate(p,catalog.fields);message(v.valid?'Valid v2 preset. Not applied yet.':v.errors.join('\n'),!v.valid);});
   $('apply-json').onclick=safe(()=>apply(JSON.parse($('json-editor').value)));
   $('sync-json').onclick=()=>{$('json-editor').value=JSON.stringify(current,null,2);message('Editor restored to the active preset.');};
   $('field-search').oninput=fields;$('field-picker').onchange=fieldChanged;$('field-op').onchange=()=>{$('field-value').disabled=['known','unknown'].includes($('field-op').value);};
   $('add-rule').onclick=safe(()=>{const p=clone(current);p.rules.push({field:$('field-picker').value,op:$('field-op').value,value:$('field-value').value,mode:$('field-mode').value,allowUnknown:$('field-unknown').checked,weight:Number($('field-weight').value)});apply(p);});
   $('add-mention').onclick=safe(()=>{const p=clone(current);p.rules.push({field:'description',op:'mentions',terms:$('mention-terms').value.split('\n').map(x=>x.trim()).filter(Boolean),excludeTerms:$('mention-excludes').value.split('\n').map(x=>x.trim()).filter(Boolean),match:$('mention-match').value,mode:$('mention-mode').value,caseSensitive:$('mention-case').checked,wholeWord:$('mention-word').checked,ignoreNegated:$('mention-negation').checked,negationWindow:Number($('mention-window').value),allowUnknown:$('mention-unknown').checked,weight:Number($('mention-weight').value)});apply(p);});
   $('clear-rules').onclick=()=>{const p=clone(current);p.rules=[];apply(p);};
   window.nearby=Object.freeze({version:2,getPreset:()=>clone(current),validatePreset:p=>PresetTools.validate(p,catalog.fields),applyPreset:p=>apply(p),importPresets:importData,exportPresets:()=>clone({version:2,presets:[...library.values()]}),getFields:()=>clone(catalog.fields),getCoverage:coverage,getResults:results,explain,reset:()=>apply(PresetTools.DEFAULT)});
   $('workspace').removeAttribute('inert');$('workspace-status').textContent='Ready · presets and rules stay in memory';emit();document.dispatchEvent(new CustomEvent('nearby:ready'));
  },
  evaluate(l,offers){return FilterEngine.evaluate(catalog?.records[l.property_id],current.rules,offers.map(unit));},
  offerMatches,matches,sortValue,coverage,
  get rules(){return clone(current.rules);},get query(){return clone(current.query);},get ready(){return ready;}
 };
})();
